begin;
create extension if not exists pgcrypto;
create type public.account_role as enum ('buyer','seller','merchant','admin');
create type public.listing_status as enum ('draft','pending_review','published','rejected','sold','archived');
create type public.listing_condition as enum ('new','used','refurbished');
create type public.transaction_mode as enum ('classified','checkout');
create type public.order_status as enum ('pending_seller','accepted','ready_for_collection','out_for_delivery','completed','cancelled','disputed');
create type public.payment_method as enum ('cash_on_collection','mobile_money','card','bank_transfer');
create type public.payment_status as enum ('pending','initiated','succeeded','failed','cancelled','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null check(char_length(display_name) between 2 and 80),phone text,avatar_url text,home_town text not null default 'Mbarara',role public.account_role not null default 'buyer',is_verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),parent_id uuid references public.categories(id) on delete set null,name text not null,slug text not null unique,icon text,is_active boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now());
create table public.listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles(id) on delete restrict,category_id uuid not null references public.categories(id) on delete restrict,title text not null check(char_length(title) between 5 and 120),slug text not null unique,description text not null check(char_length(description) between 20 and 10000),price_ugx bigint not null check(price_ugx>=0),negotiable boolean not null default false,condition public.listing_condition not null default 'used',transaction_mode public.transaction_mode not null default 'classified',status public.listing_status not null default 'pending_review',town text not null default 'Mbarara',area text,latitude numeric(9,6),longitude numeric(9,6),stock_quantity integer not null default 1 check(stock_quantity>=0),view_count bigint not null default 0 check(view_count>=0),published_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((latitude is null and longitude is null) or (latitude is not null and longitude is not null)));
create index listings_discovery_idx on public.listings(status,town,category_id,published_at desc); create index listings_price_idx on public.listings(price_ugx) where status='published'; create index listings_seller_idx on public.listings(seller_id,created_at desc); create index listings_search_idx on public.listings using gin(to_tsvector('simple',title||' '||description||' '||town));
create table public.listing_images(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings(id) on delete cascade,storage_path text not null,alt_text text,sort_order int not null default 0,created_at timestamptz not null default now(),unique(listing_id,storage_path));
create table public.saved_listings(user_id uuid not null references public.profiles(id) on delete cascade,listing_id uuid not null references public.listings(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,listing_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings(id) on delete cascade,buyer_id uuid not null references public.profiles(id) on delete cascade,seller_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(listing_id,buyer_id,seller_id),check(buyer_id<>seller_id));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 1 and 4000),read_at timestamptz,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique default('GG-'||upper(substr(encode(gen_random_bytes(8),'hex'),1,12))),buyer_id uuid not null references public.profiles(id) on delete restrict,seller_id uuid not null references public.profiles(id) on delete restrict,status public.order_status not null default 'pending_seller',payment_method public.payment_method not null default 'cash_on_collection',subtotal_ugx bigint not null check(subtotal_ugx>=0),delivery_fee_ugx bigint not null default 0 check(delivery_fee_ugx>=0),platform_fee_ugx bigint not null default 0 check(platform_fee_ugx>=0),total_ugx bigint generated always as(subtotal_ugx+delivery_fee_ugx+platform_fee_ugx) stored,delivery_mode text not null default 'collection' check(delivery_mode in('collection','local_delivery','courier')),delivery_notes text,buyer_note text,accepted_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(buyer_id<>seller_id));
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,listing_id uuid not null references public.listings(id) on delete restrict,title_snapshot text not null,unit_price_ugx bigint not null check(unit_price_ugx>=0),quantity integer not null check(quantity>0),line_total_ugx bigint generated always as(unit_price_ugx*quantity) stored);
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,provider text not null,provider_reference text,method public.payment_method not null,status public.payment_status not null default 'pending',amount_ugx bigint not null check(amount_ugx>=0),currency char(3) not null default 'UGX' check(currency='UGX'),idempotency_key text not null unique,initiated_at timestamptz,settled_at timestamptz,provider_payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(provider,provider_reference));
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,listing_id uuid references public.listings(id) on delete set null,reported_user_id uuid references public.profiles(id) on delete set null,reason text not null check(char_length(reason) between 3 and 100),details text check(details is null or char_length(details)<=4000),status text not null default 'open' check(status in('open','reviewing','actioned','dismissed')),resolution_note text,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.audit_events(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
insert into public.categories(name,slug,icon,sort_order) values('Phones & tablets','phones-tablets','phone',1),('Computers','computers','computer',2),('Fashion','fashion','fashion',3),('Home & furniture','home-furniture','home',4),('Food & agriculture','food-agriculture','produce',5),('Vehicles','vehicles','vehicle',6),('Baby & kids','baby-kids','kids',7),('Services','services','tools',8),('Property','property','house',9),('Jobs','jobs','work',10) on conflict(slug) do nothing;
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.listings enable row level security; alter table public.listing_images enable row level security; alter table public.saved_listings enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.reports enable row level security; alter table public.audit_events enable row level security;
create policy "active categories readable" on public.categories for select to anon,authenticated using(is_active);
create policy "published listings public" on public.listings for select to anon,authenticated using(status='published' or seller_id=auth.uid());
create policy "seller creates own listing" on public.listings for insert to authenticated with check(seller_id=auth.uid() and status in('draft','pending_review'));
create policy "seller updates own listing" on public.listings for update to authenticated using(seller_id=auth.uid()) with check(seller_id=auth.uid() and status in('draft','pending_review','published','sold','archived'));
create policy "seller deletes own unpublished listing" on public.listings for delete to authenticated using(seller_id=auth.uid() and status in('draft','rejected'));
create policy "users manage own saved listings" on public.saved_listings for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "conversation participants can read" on public.conversations for select to authenticated using(buyer_id=auth.uid() or seller_id=auth.uid());
create policy "buyer starts conversation" on public.conversations for insert to authenticated with check(buyer_id=auth.uid() and exists(select 1 from public.listings l where l.id=listing_id and l.status='published' and l.seller_id=seller_id));
create policy "participants read messages" on public.messages for select to authenticated using(exists(select 1 from public.conversations c where c.id=conversation_id and (c.buyer_id=auth.uid() or c.seller_id=auth.uid())));
create policy "participants send messages as themselves" on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversations c where c.id=conversation_id and (c.buyer_id=auth.uid() or c.seller_id=auth.uid())));
create policy "order participants read" on public.orders for select to authenticated using(buyer_id=auth.uid() or seller_id=auth.uid());
create policy "buyer creates own order" on public.orders for insert to authenticated with check(buyer_id=auth.uid() and status='pending_seller');
create policy "order items visible to participants" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (o.buyer_id=auth.uid() or o.seller_id=auth.uid())));
create policy "payments visible to participants" on public.payments for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (o.buyer_id=auth.uid() or o.seller_id=auth.uid())));
create policy "users submit reports" on public.reports for insert to authenticated with check(reporter_id=auth.uid());
create policy "reporter sees own reports" on public.reports for select to authenticated using(reporter_id=auth.uid());
create policy "audit events restricted" on public.audit_events for select to authenticated using(false);
-- This starter migration is not production-ready. Add profile policies, storage policies, trusted atomic checkout RPCs, admin provisioning and immutable payment transitions before launch.
commit;
